import type { FreeCamera } from "@babylonjs/lite";
import { createBankedFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface ChaseCamera {
  camera: FreeCamera;
  bank(up: Vec): void;
}

export function createChaseCamera(eye: Vec, target: Vec): ChaseCamera {
  const camera = createBankedFreeCamera(eye, target, { x: 0, y: 1, z: 0 });

  function bank(up: Vec): void {
    // Compute forward direction (from eye to target)
    const dx = target.x - eye.x;
    const dy = target.y - eye.y;
    const dz = target.z - eye.z;
    const len = Math.sqrt(dx * dx + dy * dy + dz * dz);

    if (len < 1e-8) return; // degenerate: eye == target

    const fx = dx / len;
    const fy = dy / len;
    const fz = dz / len;

    // Component of up perpendicular to forward
    const dot = up.x * fx + up.y * fy + up.z * fz;
    const upx = up.x - dot * fx;
    const upy = up.y - dot * fy;
    const upz = up.z - dot * fz;

    const perpLen = Math.sqrt(upx * upx + upy * upy + upz * upz);

    if (perpLen < 1e-6) {
      // up is (anti-)parallel to line of sight: keep previous roll
      return;
    }

    // Set the camera's up vector to the car's up direction
    // The camera will project it perpendicular to the look direction
    const uv = camera.upVector;
    uv.x = up.x;
    uv.y = up.y;
    uv.z = up.z;
  }

  return { camera, bank };
}
